# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check imports
if not any('import requests' in line for line in lines):
    raise AssertionError('Task 1: Missing "import requests"')
if not any('JSONDecodeError' in line and 'import' in line for line in lines):
    raise AssertionError('Task 1: Missing import of JSONDecodeError from requests.exceptions')

# Task 2: Check response variable
if not any('response' in line and 'requests.get' in line and 'api_url' in line for line in lines):
    raise AssertionError('Task 2: response should use requests.get(api_url)')

# Task 3: Check try block and JSON parsing
if 'try:' not in student_code:
    raise AssertionError('Task 3: Missing try block')
if not any('user_data' in line and 'response.json()' in line for line in lines):
    raise AssertionError('Task 3: Should parse JSON with response.json()')

# Task 4: Check if/else and data extraction
if 'if response.status_code == 200:' not in student_code:
    raise AssertionError('Task 4: Missing status code check')
if not any("user_data['name']" in line or 'user_data["name"]' in line for line in lines):
    raise AssertionError('Task 4: Should extract name from user_data')
if not any("user_data['email']" in line or 'user_data["email"]' in line for line in lines):
    raise AssertionError('Task 4: Should extract email from user_data')

# Task 5: Check else clause
if 'else:' not in student_code:
    raise AssertionError('Task 5: Missing else clause for failed response')
if not any('Request failed' in line and 'status_code' in line for line in lines):
    raise AssertionError('Task 5: Should print failure message with status code')

# Task 6: Check except block
if 'except JSONDecodeError:' not in student_code:
    raise AssertionError('Task 6: Missing except JSONDecodeError block')
if not any('Invalid JSON' in line for line in lines):
    raise AssertionError('Task 6: Should print "Error: Invalid JSON response"')

print('TEST_PASSED')
